#!/bin/bash
echo "=== browse newest top 12 (title | minPrice | sellers) ==="
curl -s "https://partsbazar360.realtrackapp.com/api/search/parts?sort=newest&limit=12" \
  | python3 -c 'import sys,json; d=json.load(sys.stdin); print("total",d.get("total")); [print(i.get("title"),"|",i.get("minPrice"),"|",[o.get("sellerName") for o in i.get("offers",[])]) for i in d.get("items",[])[:12]]'

echo
echo "=== scan newest 60 for non-English heuristics ==="
curl -s "https://partsbazar360.realtrackapp.com/api/search/parts?sort=newest&limit=60" \
  | python3 -c 'import sys,json,re; d=json.load(sys.stdin); rx=re.compile(r"\b(albero|coperchio|pompa|altoparlante|sterzo|cinghia|motore|anteriore|posteriore|destra|sinistra|volant|modanatura|passaruota|pannello|bilanciere|occasion|schermo|portiera|cofano|parafango|sospension|frenata|cremagliera|pignone|biella|boccola|raccordo|regolazione|rinforzo|comando|braccio|inferiore|superiore|raccolta|iniezione|secondaria|trasmissione|accessori|termostato|cuscino|paraurti|specchio|fanale|scatola|tubo|olio|acqua|montante|cuscinetto|ammortizzatore|tirante|barra|ponte|differenziale|giunto|omocinetico|scudo|maniglia|chiusura|serratura|cassetto|plancia|cruscotto|climatizzatore|compressore|alternatore|motorino|centralina|sensore|sonda|lambdasonda|candeletta|bobina|cavo|fusibile|relè|relais|pompetta|collettore|aspirazione|scarico|marmitta|silenzioso|longherone|traversa|parabrezza|lunotto|finestrino|vetrino|vetro|retrovisore|specchietto|condotto|quadro|strumenti|presa|bocchettone|bocchetta|flusso|miscela|soffietto|mantice|deflettore|paraschizzi|copertura|guscio|carena|carenatura|griglia|mascherina|calandra|fascione|listello|cornice|portellone|portone|baule|vano|sfiato|roue|pneu|capot|glace|phares|hayon|aile|rotule|roulement|bague|durit|frein|amort|essieu|boîte|boite|embrayage|vilebrequin|soupape|injecteur|carburant|échappement|silencieux|catalyseur|disque|étrier|plaquette|tambour|getriebe|schaltung|hinter|vorder|lenk|brems|feder|dämpf|stoß|stoss|abgas|auspuff|kotfl|tür|haube|scheibe|scheinwerfer|rück|seiten|spiegel|kasten|halter|lager|buchse|bolzen|nabe|achse|lenker|stabil|quer|ölpumpe|wasserpumpe|zahnriemen|keilriemen|kurbel|nocken|zylinder|kolben|pleuel|ventil|zünd|einspritz|kraftstoff|luftfilter|ölkühler|bremsscheibe|bremse|handbremse|antriebswelle|gelenk|kupplung|differenzial|gebraucht|rueda|neumático|parachoques|paragolpes|espejo|farol|guardabarro|aleta|puerta|maletero|cofre|volante|dirección|amortiguador|muelle|suspensión|mangueta|rótula|rodamiento|embrague|cigüeñal|inyector|filtro|silenciador|pinza|pastilla)\b",re.I); bad=[i.get("title") for i in d.get("items",[]) if rx.search(i.get("title") or "")]; print("non_english_found:",len(bad)); [print("  ",t) for t in bad]'

echo
echo "=== sample PDP (first FEBEST result) ==="
PID=$(curl -s "https://partsbazar360.realtrackapp.com/api/search/parts?q=FEBEST&limit=1" | python3 -c 'import sys,json; print(json.load(sys.stdin)["items"][0]["id"])')
echo "part_id=$PID"
curl -s "https://partsbazar360.realtrackapp.com/api/search/parts/$PID" \
  | python3 -c 'import sys,json; d=json.load(sys.stdin); print("title:",d.get("title")); print("brand:",d.get("brand")); print("num_images:",len(d.get("imageUrls") or [])); print("imageUrls:",(d.get("imageUrls") or [])[:3]); ct=d.get("compatibilityTable") or []; print("compat_rows:",len(ct)); print("mvl_verified:",sum(1 for r in ct if r.get("mvlVerified")),"/",len(ct)); print("sample_row:",ct[0] if ct else None); print("sellers:",[o.get("sellerName") for o in d.get("offers",[])])'
